# Hard-coded, normalized DCT-I weights for Chebyshev-Lobatto fitting
# Supported polynomial degrees: M = 3:30
# W[j+1,m+1] = (2/M)*endpoint(j)*endpoint(m)*cos(pi*j*m/M), j,m = 0:M, endpoint(q) = 0.5 at q = 0 or M, and 1.0 otherwise
# See bessels_core.jl for the why and usage of these weights

# to generate own weights for M use _chebfit_make_weights(M)
function _chebfit_make_weights(M::Int)::Matrix{Float64}
    W=Matrix{Float64}(undef,M+1,M+1)
    final_mul=2.0/M
    @inbounds for m in 0:M
        endpoint_m=(m==0 || m==M) ? 0.5 : 1.0
        for j in 0:M
            endpoint_j=(j==0 || j==M) ? 0.5 : 1.0
            W[j+1,m+1]=final_mul*endpoint_j*endpoint_m*cospi(j*m/M)
        end
    end
    return W
end

